#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

typedef struct TreeNode {
    int val;
    struct TreeNode *left;
    struct TreeNode *right;
} TreeNode;

typedef struct Entry {
    long long key;
    int count;
    int used;
} Entry;

#define TABLE_SIZE 4096
static Entry table[TABLE_SIZE];

static size_t hash64(long long x) {
    uint64_t z = (uint64_t)x;
    z ^= z >> 33;
    z *= UINT64_C(0xff51afd7ed558ccd);
    z ^= z >> 33;
    z *= UINT64_C(0xc4ceb9fe1a85ec53);
    z ^= z >> 33;
    return (size_t)(z & (TABLE_SIZE - 1));
}

static int mapGet(long long key) {
    size_t i = hash64(key);
    for (size_t step = 0; step < TABLE_SIZE; ++step) {
        Entry *e = &table[i];
        if (!e->used) return 0;
        if (e->key == key) return e->count;
        i = (i + 1) & (TABLE_SIZE - 1);
    }
    return 0;
}

static void mapAdd(long long key) {
    size_t i = hash64(key);
    for (;;) {
        Entry *e = &table[i];
        if (!e->used) { e->used = 1; e->key = key; e->count = 1; return; }
        if (e->key == key) { ++e->count; return; }
        i = (i + 1) & (TABLE_SIZE - 1);
    }
}

static void mapRemove(long long key) {
    size_t i = hash64(key);
    for (;;) {
        Entry *e = &table[i];
        if (!e->used) return;
        if (e->key == key) {
            if (--e->count > 0) return;

            /* Remove the slot and reinsert the following cluster so that
               open-addressing lookups remain correct after deletion. */
            e->used = 0;
            size_t j = (i + 1) & (TABLE_SIZE - 1);
            while (table[j].used) {
                Entry moved = table[j];
                table[j].used = 0;
                size_t k = hash64(moved.key);
                while (table[k].used) k = (k + 1) & (TABLE_SIZE - 1);
                table[k] = moved;
                j = (j + 1) & (TABLE_SIZE - 1);
            }
            return;
        }
        i = (i + 1) & (TABLE_SIZE - 1);
    }
}

static int dfs(TreeNode *root, long long current, int targetSum) {
    if (!root) return 0;
    current += root->val;
    int ans = mapGet(current - targetSum);
    mapAdd(current);
    ans += dfs(root->left, current, targetSum);
    ans += dfs(root->right, current, targetSum);
    mapRemove(current);
    return ans;
}

int pathSum(TreeNode *root, int targetSum) {
    memset(table, 0, sizeof(table));
    mapAdd(0);
    return dfs(root, 0, targetSum);
}

static void freeTree(TreeNode *root) {
    if (!root) return;
    freeTree(root->left);
    freeTree(root->right);
    free(root);
}

