class Solution {
    private final Map<Long, Integer> freq = new HashMap<>();
    private long target;

    private int dfs(TreeNode node, long prefix) {
        if (node == null) return 0;
        prefix += node.val;
        int ans = freq.getOrDefault(prefix - target, 0);
        freq.put(prefix, freq.getOrDefault(prefix, 0) + 1);
        ans += dfs(node.left, prefix);
        ans += dfs(node.right, prefix);
        int left = freq.get(prefix) - 1;
        if (left == 0) freq.remove(prefix);
        else freq.put(prefix, left);
        return ans;
    }

    public int pathSum(TreeNode root, int targetSum) {
        target = targetSum;
        freq.clear();
        freq.put(0L, 1);
        return dfs(root, 0L);
    }
}

